    if (response.status !== 'completed') throw new Error('incomplete_response');
    const parsed = responseSchema.safeParse(JSON.parse(response.output_text));
    if (!parsed.success || parsed.data.message.length > 1000 || /[\r\n]/.test(parsed.data.message)) throw new Error('invalid_response');
    return { ok: true as const, message: parsed.data.message, model: response.model, latencyMs: Date.now() - started, usage: response.usage ?? null };
  } catch (error) {
    return { ok: false as const, template: prepared.template, model, latencyMs: Date.now() - started, error: error instanceof Error ? error.name + ': ' + error.message : 'generation_error' };
  }
}
